{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In humans, only about 1.2% of a 6 mg synthetic lycopene dose dispersed in oil appeared in the blood circulation, showing that a large lipophilic isoprenoid can have very low systemic availability; this supports low F for the similarly large, lipophilic isoprenoid-tailed ubiquinone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Only 0.17% of a 23.6 mg lycopene dose in tomato paste reached the circulation in humans, another direct low systemic-availability measurement for a lipophilic isoprenoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Phytoene, a less conjugated C40 isoprenoid with higher Morgan similarity to the query, was estimated to be 58.5% absorbed in humans; this is the strongest structural analog supporting high F, but its lack of a polar quinone head and lower molecular weight limit transferability to ubiquinone-10.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "In healthy subjects consuming 10.2 mg 13C-lycopene, all-trans lycopene bioavailability was estimated at 23.2% ± 8%, above the 20% threshold; however, this labeled-tracer compartmental estimate contrasts with systemic-availability measurements and is less endpoint-matched for absolute oral bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low (F < 20%) because the query is ubiquinone-10, a very large, highly lipophilic molecule with a long isoprenoid tail and polar quinone head; the most endpoint-matched lipophilic isoprenoid evidence (lycopene) shows low systemic availability, while the high phytoene and labeled-lycopene estimates are less transferable or less endpoint-matched.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone-10/CoQ10 in the evidence set.",
    "Carotenoid analogs differ in head group, molecular weight, and conjugation; lycopene estimates vary widely by method and formulation.",
    "Phytoene high bioavailability may not transfer because it lacks the quinone head and has a much lower molecular weight."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

